sp_widget.client_script:
function a($scope, spUtil, $location, spAriaFocusManager) {

	$scope.$on('data_table.click', function(e, parms){
		var p = 'kotak_forms';
		var s = {id: p, table: parms.table, sys_id: parms.sys_id, view: 'kotak_uw_case'};

		if($scope.data.page == 'nedmed_user'){

			var newURL = $location.search(s);
			spAriaFocusManager.navigateToLink(newURL.url());
		}


	});
}

sp_widget.script:
(function(){
	/*  "use strict"; - linter issues */
	// populate the 'data' object

	data.page = $sp.getParameter('id');
	var sp_page = $sp.getValue('sp_page');
	var pageGR = new GlideRecord('sp_page');
	pageGR.get(sp_page);
	data.page_id = pageGR.getValue("id");
	$sp.getValues(data);
	if (data.field_list) {
		data.fields_array = data.field_list.split(',');
	} else {
		data.field_list = $sp.getListColumns(data.table);
	}

	if (input) {
		data.p = input.p;
		data.o = input.o;
		data.d = input.d;
		data.q = input.q;
	}
	data.p = data.p || 1;
	data.o = data.o || $sp.getValue('order_by');
	data.d = data.d || $sp.getValue('order_direction');

	data.page_index = (data.p - 1);
	data.window_size = $sp.getValue('maximum_entries') || 10;
	data.window_start  = (data.page_index * data.window_size);
	data.window_end = (((data.page_index + 1) * data.window_size));
	data.filter = $sp.getValue("filter");

	var gr = new GlideRecordSecure(data.table);
	if (!gr.isValid()) {
		data.invalid_table = true;
		data.table_label = data.table;
		return;
	}
	data.table_label = gr.getLabel();

	options.table = data.table;
	options.fields = data.field_list;
	options.o=data.o;
	options.d= data.d;
	options.filter=data.filter;
	options.window_size=data.window_size;
	options.view = data.view;
	options.useInstanceTitle = true; 
	options.headerTitle = options.title;
	options.button_page = options.button_page;
	options.button_name_1 = options.button_name_1;
	options.show_sub_button_1= options.show_sub_button_1;
	options.button_page_1 = options.button_page_1;
	options.Column1 = options.Column1;
	options.column2 = options.column2;
	options.show_breadcrumbs=false;
	options.show_sub_button=options.show_sub_button;
	options.show_toggle=options.show_toggle;
	options.toggle_field=options.toggle_field;
	options.show_new=options.show_new;
	data.dataTableWidget = $sp.getWidget('kli_list_filter', options);
})();
